using System.IO;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class GeneratedFormatterLogicReceipts
{
    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.CSharp12);

    [Fact]
    public async Task AttributedDataTypeFromReferencedAssembly_IgnoreMemberIsHonoured()
    {
        List<MetadataReference> refs = await GetReferencesAsync();
        string projectA = """
            namespace ProjectA
            {
                [MessagePack.MessagePackObject]
                public class MyType
                {
                    [MessagePack.Key(0)]
                    public int Id { get; set; }

                    [MessagePack.IgnoreMember]
                    public int SecretValue { get; set; }
                }
            }
            """;
        CSharpCompilation a = CSharpCompilation.Create(
            "ProjectA",
            new[] { CSharpSyntaxTree.ParseText(projectA, ParseOptions) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using MemoryStream ms = new();
        var emit = a.Emit(ms);
        Assert.True(emit.Success, string.Join(Environment.NewLine, emit.Diagnostics));
        refs.Add(MetadataReference.CreateFromImage(ms.ToArray()));

        string projectB = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [GeneratedMessagePackResolver]
                partial class MyResolver { }

                [GeneratedMessagePackFormatter]
                partial class MyTypeFormatter : IMessagePackFormatter<ProjectA.MyType> { }
            }
            """;
        GeneratorDriverRunResult result = RunGenerator(projectB, refs);
        string[] formatterSources = result.GeneratedTrees
            .Select(t => t.ToString())
            .Where(s => s.Contains("MyTypeFormatter") && s.Contains("Serialize("))
            .ToArray();
        Assert.NotEmpty(formatterSources);
        Assert.All(formatterSources, s => Assert.DoesNotContain("SecretValue", s));
    }

    [Fact]
    public async Task FormatterImplementingTwoDataTypes_ReportsMsgPack020()
    {
        List<MetadataReference> refs = await GetReferencesAsync();
        string source = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                public class A { public int X { get; set; } }

                public class B { public int Y { get; set; } }

                [GeneratedMessagePackResolver]
                partial class MyResolver { }

                [GeneratedMessagePackFormatter]
                partial class TwoFormatter : IMessagePackFormatter<A>, IMessagePackFormatter<B> { }
            }
            """;
        GeneratorDriverRunResult result = RunGenerator(source, refs);
        Assert.Contains(result.Diagnostics, d => d.Id == "MsgPack020");
    }

    private static async Task<List<MetadataReference>> GetReferencesAsync()
    {
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> refs = new(framework);
        refs.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        return refs;
    }

    private static GeneratorDriverRunResult RunGenerator(string source, IEnumerable<MetadataReference> refs)
    {
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ProjectB",
            new[] { CSharpSyntaxTree.ParseText(source, ParseOptions) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: ParseOptions);
        driver = driver.RunGenerators(compilation);
        return driver.GetRunResult();
    }
}
